import{_ as e,c as t,o as r,ae as o}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/troubleshooting.md","filePath":"ja/guide/troubleshooting.md","lastUpdated":1795170900000}'),i={name:"ja/guide/troubleshooting.md"};function l(n,a,h,s,d,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><p>よくある問題とその解決方法。</p><h2 id="ページが開かない" tabindex="-1">ページが開かない <a class="header-anchor" href="#ページが開かない" aria-label="Permalink to &quot;ページが開かない&quot;">​</a></h2><ul><li>他のサイトが開けるか確認してから、⌘R で再読み込みしてください。</li><li>広告ブロックのルールを有効にしている場合、一時的に止めて原因を確かめてください。</li><li>プライベートウィンドウ（⌘⇧N）で試してください。そこで開ける場合は、設定からそのサイトの Cookie を削除してください。</li></ul><h2 id="ダウンロードが止まる・途中で終わる" tabindex="-1">ダウンロードが止まる・途中で終わる <a class="header-anchor" href="#ダウンロードが止まる・途中で終わる" aria-label="Permalink to &quot;ダウンロードが止まる・途中で終わる&quot;">​</a></h2><ul><li>ダウンロードパネルで一時停止してから再開してください。</li><li>ページから保存した動画が失敗したら、途中のファイルを削除して再度お試しください。分割動画は MP4 に結合され、失敗した場合は元の分割ファイルがダウンロードフォルダに残ります。</li></ul><h2 id="ブックマークが読み込めない" tabindex="-1">ブックマークが読み込めない <a class="header-anchor" href="#ブックマークが読み込めない" aria-label="Permalink to &quot;ブックマークが読み込めない&quot;">​</a></h2><p>まず旧ブラウザーでブックマークを HTML ファイルに書き出し、Persim のブックマークマネージャーで「HTML を読み込む」を選んでください。フォルダーや重複リンクは自動で整理されます。</p><h2 id="動画が見つからない" tabindex="-1">動画が見つからない <a class="header-anchor" href="#動画が見つからない" aria-label="Permalink to &quot;動画が見つからない&quot;">​</a></h2><p>すべてのサイトで動画を保存できるわけではありません。対象ページでメディアパネルを開いてみてください。何も表示されない場合、そのサイトの再生方式では直接保存できません。</p><h2 id="動作が重い" tabindex="-1">動作が重い <a class="header-anchor" href="#動作が重い" aria-label="Permalink to &quot;動作が重い&quot;">​</a></h2><p>使っていないタブを閉じるか、不要になった広告ブロックの購読を無効にしてください。サイトの権限は設定で確認できます。</p><h2 id="解決しない場合" tabindex="-1">解決しない場合 <a class="header-anchor" href="#解決しない場合" aria-label="Permalink to &quot;解決しない場合&quot;">​</a></h2><p><strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> まで、何をしようとしていたか（可能ならスクリーンショットも）をお知らせください。</p>',14)])])}const m=e(i,[["render",l]]);export{p as __pageData,m as default};
